import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])

    if n == 0:
        print("")
        return

    goals = list(map(int, data[1:n+1]))

    result = []
    for i in range(n):
        if i < 3:
            # Sum all previous teams (indices 0 to i-1)
            sum_prev = sum(goals[:i]) if i > 0 else 0
        else:
            # Sum last 3 teams (indices i-3 to i-1)
            sum_prev = sum(goals[i-3:i])

        net_rate = goals[i] - sum_prev
        result.append(str(net_rate))

    print(" ".join(result))

if __name__ == "__main__":
    main()
